// Compatibility wrapper: the machine instantiates this module with the old
// c64_video port list.  The picture is generated by c64video.v with the
// Tang/C64Nano-style 1008x624 timing on the same 31.25 MHz clock as the core.

`timescale 1ns / 1ps
`default_nettype none

module c64_video (
	input wire clk_sys,
	input wire clk_vid,
	input wire reset,
	input wire disk_act,
	input wire disk_wr,
	input wire tape_act,
	input wire tape_wr,

	// VIC-II output (clk_sys)
	input wire [7:0] vic_r,
	input wire [7:0] vic_g,
	input wire [7:0] vic_b,
	input wire vic_hsync,
	input wire vic_vsync,
	input wire vic_pixel_ce,
	input wire pause,

	// HDMI timing (clk_vid)
	output wire [23:0] rgb,
	output wire        hs,
	output wire        vs,
	output wire        de
);

wire [7:0] profi_r, profi_g, profi_b;
wire profi_hs, profi_vs, profi_de;

// Fixed window, no OSD centering: 720x576 visible, 1008x624 total at
// 31.25 MHz.  The source VIC frame is exactly 624 output lines.
c64video #(
	.H_ACTIVE      (720),
	.H_TOTAL       (1008),
	.V_ACTIVE      (576),
	.V_CONTENT     (544),
	.V_OFFSET      (16),
	.V_TOTAL       (624),
	.H_SYNC_START  (720 + 24),
	.H_SYNC_END    (720 + 24 + 72),
	.V_SYNC_START  (581),
	.V_SYNC_END    (586),
	.SRC_PIX       (504),
	.SRC_LINE0     (26),
	.SRC_X0        (12),
	.LAG           (2),
	.X_LOAD        (396),
	.X_DELAY       (0),
	.H_VIEW        (720),
	.X_STEP_NUM    (1),
	.X_STEP_DEN    (2),
	.STALL_MAX     (40),
	.MASK_BLANK    (1)
) profi (
	.clk_sys       (clk_sys),
	.clk_vid       (clk_vid),
	.rst           (reset),
	.disk_act      (disk_act),
	.disk_wr       (disk_wr),
	.tape_act      (tape_act),
	.tape_wr       (tape_wr),
	.vic_r         (vic_r),
	.vic_g         (vic_g),
	.vic_b         (vic_b),
	.vic_hblank    (vic_hsync),
	.vic_vblank    (vic_vsync),
	.vic_pixel_ce  (vic_pixel_ce),
	.out_r         (profi_r),
	.out_g         (profi_g),
	.out_b         (profi_b),
	.out_hs        (profi_hs),
	.out_vs        (profi_vs),
	.out_de        (profi_de)
);

assign hs  = profi_hs;
assign vs  = profi_vs;
assign de  = profi_de;

assign rgb = {profi_r, profi_g, profi_b};

endmodule
`default_nettype wire
